<?php
require_once __DIR__.'/config/config.php';
$sent=!empty($_SESSION['volunteer_registration_sent']);unset($_SESSION['volunteer_registration_sent']);$error='';
$types=['Medical volunteer','Driver','Search & rescue','Food distribution','Shelter volunteer','Translator','Drone operator','Engineer','IT volunteer','Blood donor'];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&isset($_POST['register_volunteer'])){
 verify_csrf();
 $name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');
 $emergencyName=trim($_POST['emergency_contact_name']??'');$emergencyPhone=trim($_POST['emergency_contact_phone']??'');
 $type=trim($_POST['volunteer_type']??'');$location=trim($_POST['location']??'');$availability=$_POST['availability']??'ON_CALL';
 $skills=trim($_POST['skills']??'');$roleDetails=trim($_POST['role_details']??'');$languages=trim($_POST['languages']??'');
 $bloodType=trim($_POST['blood_type']??'');$lastDonation=trim($_POST['last_donation_date']??'');
 if(trim($_POST['website']??'')!=='')$error='Your registration could not be accepted.';
 elseif($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone===''||$emergencyName===''||$emergencyPhone===''||!in_array($type,$types,true)||$location===''||!in_array($availability,['AVAILABLE','ON_CALL','UNAVAILABLE'],true)||!isset($_POST['consent_confirmed']))$error='Please complete all required fields and confirm consent.';
 elseif($type==='Blood donor'&&$bloodType==='')$error='Please provide your blood type.';
 elseif($bloodType!==''&&!in_array($bloodType,['A+','A-','B+','B-','AB+','AB-','O+','O-','Unknown'],true))$error='Please select a valid blood type.';
 else{try{$s=db()->prepare('INSERT INTO volunteers(full_name,email,phone,emergency_contact_name,emergency_contact_phone,volunteer_type,location,availability,skills,role_details,languages,blood_type,last_donation_date,consent_confirmed) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1)');$s->execute([$name,$email,$phone,$emergencyName,$emergencyPhone,$type,$location,$availability,$skills?:null,$roleDetails?:null,$languages?:null,$bloodType?:null,$lastDonation?:null]);$_SESSION['volunteer_registration_sent']=true;redirect('/volunteer.php');}catch(Throwable $e){$error='We could not save your registration right now. Please try again later.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Register disaster-response skills and connect with authorized organizations supporting communities across Nepal."><title>Volunteer Network - Nepal Disaster Archive</title><link rel="canonical" href="<?=e(absolute_url('/volunteer'))?>"><style>:root{--ink:#17202a;--paper:#f7f3ed;--red:#9e2b25;--green:#263d3a;--line:#d9d0c6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,serif}.nav{position:sticky;top:0;background:#111820;color:#fff;z-index:2;padding:15px 5%;display:flex;align-items:center;gap:25px;font:13px Arial}.nav a{color:#fff;text-decoration:none}.logo{font-weight:900;letter-spacing:2px}.navlinks{margin-left:auto;display:flex;gap:18px}.hero{padding:75px 7% 60px;background:var(--green);color:#fff}.wrap{width:min(1100px,90%);margin:auto}.hero h1{font-size:clamp(44px,7vw,80px);line-height:.95;margin:15px 0 25px}.hero p{font-size:21px;line-height:1.6;color:#dce4df;max-width:760px}.section{padding:60px 0}.intro{font-size:19px;line-height:1.7;color:#555;max-width:800px}.form{background:#fff;border:1px solid var(--line);border-radius:8px;padding:28px;max-width:900px;margin-top:35px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:grid;gap:7px}.full{grid-column:1/-1}label{font:14px Arial}input,select,textarea{font:15px Arial;border:1px solid #cfc8bf;border-radius:6px;padding:12px;background:#fff}textarea{min-height:120px;resize:vertical}button{background:var(--red);color:#fff;border:0;border-radius:6px;padding:13px 18px;font:700 15px Arial;cursor:pointer}.notice{padding:13px 16px;background:#eee7db;border-left:4px solid var(--red);font:15px Arial;margin:20px 0}.fine{color:#666;font:13px/1.6 Arial}.conditional{display:none}.conditional.visible{display:grid}.trap{display:none}@media(max-width:700px){.navlinks{display:none}.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><?php require_once __DIR__ . '/includes/public-nav.php'; ?><header class="hero"><div class="wrap"><div style="font:800 12px Arial;text-transform:uppercase;letter-spacing:1px;color:#e5b5a9">Community response · Nepal</div><h1>Volunteer Network</h1><p>Register your skills so authorized disaster-response organizations can find available help when communities need it most.</p></div></header><main class="section"><div class="wrap"><h2>Register as a volunteer</h2><p class="intro">Choose the role that best describes how you can help. Your registration will be reviewed before it is shared with response coordinators.</p><?php if($sent):?><div class="notice">Thank you. Your registration has been received and will be reviewed by the archive team.</div><?php elseif($error):?><div class="notice"><?=e($error)?></div><?php endif;?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="register_volunteer" value="1"><div class="trap"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="grid"><label class="field">Full name *<input name="full_name" required></label><label class="field">Email *<input type="email" name="email" required></label><label class="field">Phone *<input name="phone" required></label><label class="field">Emergency contact name *<input name="emergency_contact_name" required></label><label class="field">Emergency contact phone *<input name="emergency_contact_phone" required></label><label class="field">Volunteer role *<select name="volunteer_type" id="volunteer-type" required><option value="">Select a role</option><?php foreach($types as $type):?><option value="<?=e($type)?>"><?=e($type)?></option><?php endforeach;?></select></label><label class="field">Location *<input name="location" placeholder="District, municipality, or area" required></label><label class="field">Availability *<select name="availability" required><option value="ON_CALL">On call</option><option value="AVAILABLE">Available now</option><option value="UNAVAILABLE">Currently unavailable</option></select></label><label class="field full">Skills or relevant experience<textarea name="skills" placeholder="Certifications, years of experience, or other useful skills..."></textarea></label><label class="field full conditional" id="role-details-label">Role-specific details<textarea name="role_details" id="role-details"></textarea></label><label class="field full conditional" id="languages-label">Languages spoken<input name="languages" placeholder="For example: Nepali, Maithili, English"></label><label class="field conditional" id="blood-type-label">Blood type<select name="blood_type"><option value="">Select blood type</option><option>A+</option><option>A-</option><option>B+</option><option>B-</option><option>AB+</option><option>AB-</option><option>O+</option><option>O-</option><option>Unknown</option></select></label><label class="field conditional" id="last-donation-label">Last donation date<input type="date" name="last_donation_date"></label><label class="full"><input type="checkbox" name="consent_confirmed" required> I consent to authorized disaster-response organizations contacting me about volunteer work. *</label><button class="full" type="submit">Register as volunteer</button></div></form><p class="fine">Please do not use this form for emergency requests. Call local emergency services or use the Emergency Help page.</p></div></main><script>var typeSelect=document.getElementById('volunteer-type'),details=document.getElementById('role-details-label'),languages=document.getElementById('languages-label'),blood=document.getElementById('blood-type-label'),donation=document.getElementById('last-donation-label'),detailsInput=document.getElementById('role-details');function updateFields(){var type=typeSelect.value;details.classList.toggle('visible',type!=='');languages.classList.toggle('visible',type==='Translator');blood.classList.toggle('visible',type==='Blood donor');donation.classList.toggle('visible',type==='Blood donor');detailsInput.placeholder=type==='Driver'?'License category, vehicle type, passenger or cargo capacity...':type==='Medical volunteer'?'Qualification, license, first-aid or clinical training...':type==='Drone operator'?'Drone model, pilot certification, mapping or thermal-imaging equipment...':type==='Engineer'?'Engineering discipline, license, structural or field experience...':type==='IT volunteer'?'Systems, networks, communications, mapping, or software skills...':type==='Search & rescue'?'Rescue training, equipment, climbing or first-aid experience...':'Relevant experience for this role...'}typeSelect.addEventListener('change',updateFields);</script><?php require __DIR__.'/includes/public-footer.php'; ?></body></html>
